from common import *

def make(v):
    p=Paper(2015,v);k=v+2
    # Consecutive squares with a perfect square difference, as in the reference.
    a=((2*k+19)**2+1)//2
    p.mc('Difference of squares',f'√({a}²−{a-1}²) утгыг ол.',2*k+19,'a²−(a−1)²=2a−1; өгсөн тохиолдолд төгс квадрат.')
    p.mc('Exponential inequality',f'2^x≤{2**(k+1)} тэнцэтгэл бишийг бод.',f'(−∞; {k+1}]','Суурь 2>1 тул зэргийн өсөх чанар хэрэглэнэ.',[f'[{k+1}; +∞)',f'(−∞; {k+1})',f'({k+1}; +∞)','R'])
    angle=15*(k+1)
    p.mc('Degrees to radians',f'{angle}° өнцгийг радианд шилжүүл.',f'{F(angle,180)}π','Градусыг π/180-аар үржүүл.',[f'{F(angle,90)}π',f'{F(angle,360)}π',f'{F(angle+15,180)}π',f'{F(angle-15,180)}π'])
    p.mc('Linear derivative',f'y=−{k}x+{k+4} функцийн уламжлалыг ол.',-k,'Шулууны налалт уламжлалтай тэнцүү.')
    p.mc('Right triangle angle',f'Тэгш өнцөгт гурвалжны нэг хурц өнцөг {15+5*v}°. Нөгөөг ол.',75-5*v,'Хоёр хурц өнцгийн нийлбэр 90°.')
    p.mc('Log power',f'(log₃9)^(log₂{k+4}) утгыг ол.',k+4,'log₃9=2, дараа нь 2^(log₂t)=t.')
    power=2019+v
    p.mc('Last digit',f'7^{power} тооны сүүлийн цифр хэд вэ?',pow(7,power,10),'7-ийн зэргийн сүүлийн цифр 7,9,3,1 гэсэн дөрвөн мөчлөгтэй.',[n for n in [1,3,7,9,5] if n!=pow(7,power,10)])
    p.mc('Drying mass',f'Өвс хатаахад массынхаа 1/5-ийг алддаг. {80+8*k} тонн хуурай өвс авахын тулд хэдэн тонн нойтон өвс хэрэгтэй вэ?',100+10*k,'Хуурай масс анхны массын 4/5 тул 5/4-өөр үржүүл.')
    p.mc('Powers of a base below one',f'a=(1/{k})⁸, b=(1/{k})^(1/4), c=(1/{k})², d=(1/{k})^(1/5). Багаас их рүү эрэмбэл.','a,c,b,d','0<суурь<1 тул илтгэгч их байх тусам утга бага: 8>2>1/4>1/5.', ['d,b,c,a','a,c,d,b','c,a,b,d','a,b,c,d'])
    p.mc('Cosine rule',f'PQ={3*k}, PR={8*k}, ∠QPR=60°. QR-ийг ол.',7*k,'QR²=9k²+64k²−24k²=49k².')
    p.mc('Parity','Аль нь тэгш функц вэ?',f'x²+cos({k}x)','Квадрат болон cos хоёулаа тэгш.',[f'x+cos({k}x)',f'x sin²({k}x)',f'sin({k}x)',f'x³+{k}'])
    p.mc('Area probability',f'Радиус {k} дугуй дотроос цэг жигд сонгоно. Төвөөс {F(k,4)}-ээс бага зайд байх магадлалыг ол.',F(1,16),'Талбайн харьцаа (R/4)²/R²=1/16.')
    repeat=11+2*v
    p.mc('Repeating rational',f'2.0({repeat:02}) үет бутархайг энгийн бутархай болго.',F(1980+repeat,990),'Үегүй 0 цифрийн дараа хоёр цифрийн үе: 2+repeat/990.')
    n=k+7
    p.mc('Polygon diagonals',f'Гүдгэр {n} өнцөгт хэдэн диагональтай вэ?',n*(n-3)//2,'Орой бүрээс n−3 диагональ, давхар тоолсныг 2-т хуваана.')
    p.mc('Double quadratic root',f'x²−{2*k}x+c=0 тэнцэтгэл тэнцүү язгууртай байх c-г ол.',k*k,'Дискриминант (2k)²−4c=0.')
    p.mc('Square minus circle',f'{2*k} талтай квадратад багтсан дугуйн гаднах, квадрат доторх хэсгийн талбайг ол.',f'{k*k}(4−π)','Квадратын талбай 4k²-ээс дугуйн πk²-ийг хас.',[f'{k*k}(4+π)',f'{4*k*k}π',f'{k*k}π',f'{2*k}(4−π)'])
    b=k+2
    p.mc('Rational exponential equation',f'({b}^(x+2)−{b**3})/({b}^(2x)−{b*b})={b}/({b+1}) тэгшитгэлийг бод.',2,'u=b^x. Хүртвэр b²(u−b), хуваарь (u−b)(u+b); u≠b. Хураагаад u=b², иймд x=2.',wrong=[0,1,3,-1])
    p.mc('Alternating infinite radical',f'X=√({k}√({k+2}√({k}√({k+2}…)))) эерэг хязгаартай. X-ийг ол.',f'∛{k*k*(k+2)}','Y=√((k+2)X), X²=kY. Тэгвэл X⁴=k²(k+2)X, X³=k²(k+2).',[f'√{k*(k+2)}',f'∛{k*(k+2)**2}',f'{k+2}',f'{k}'])
    p.mc('Angle bisector ratio',f'PQR гурвалжны Q өнцгийн биссектрис PR-ийг K дээр огтолно. PQ={2*k}, QR={3*k}, PK={k+1}. KR-ийг ол.',F(3*(k+1),2),'PK/KR=PQ/QR=2/3.')
    divisor=k+2;res=v
    count=sum(i%divisor==res for i in range(100,1000))
    p.mc('Counting residue class',f'{divisor}-д хуваахад {res} үлдэгдэл өгдөг гурван оронтой тоо хэд вэ?',count,'100-999 дундах тохирох эхний ба сүүлийн гишүүнийг олж арифметик прогрессийн тоог бод.')
    p.mc('Absolute inequality',f'|x−{k+2}|<{k} тэнцэтгэл бишийг бод.',f'(2; {2*k+2})','−k<x−k−2<k.',[f'[2; {2*k+2}]',f'(−∞; 2) ∪ ({2*k+2}; +∞)',f'(−2; {2*k+2})',f'(2; {2*k})'])
    s=k;u2=s*s-2;u4=u2*u2-2
    p.mc('Vieta power sum',f'x₁,x₂ нь x²−{s}x+1=0-ийн язгуурууд. x₁⁴+x₂⁴-г ол.',u4,'x₁²+x₂²=s²−2; дөрөвдүгээр зэргийн нийлбэр (s²−2)²−2.')
    # D(1-4(1/16+1/8))=D/4; remaining distance chosen.
    rem=40+8*k;D=4*rem
    p.mc('Opposing travel',f'Хоёр суурингаас хоёр автобус нэгэн зэрэг угталцан хөдөлнө. Бүх замыг нэг нь 16, нөгөө нь 8 цагт туулна. Дөрвөн цагийн дараа уулзаагүй, хоорондоо {rem} км зайтай байв. Хурдны нийлбэрийг ол.',F(3*D,16),'Зам D гэвэл дөрвөн цагт 3D/4 явна. Үлдсэн D/4=rem. Хурдны нийлбэр 3D/16.')
    p.mc('Off-axis cylinder section',f'Радиус {5*k}, өндөр {8*k} цилиндрийг тэнхлэгтэй параллель хавтгайгаар огтлоход квадрат үүсэв. Огтлох хавтгай тэнхлэгээс ямар зайтай вэ?',3*k,'Огтлолын өргөн 8k, хагас хөвч 4k. Зай √((5k)²−(4k)²)=3k.')
    p.mc('Cubic decreasing interval',f'y=x³−{3*k}x²−{9*k*k}x+12 функцийн буурах завсрыг ол.',f'(−{k}; {3*k})','y′=3(x+k)(x−3k)<0 язгууруудын хооронд.',[f'(−∞; −{k})',f'({3*k}; +∞)',f'(−{3*k}; {k})','R'])
    a=20+k;b=100+2*k
    p.mc('Telescoping sum',f'Σ[n={a}…{b-1}] 2/(n(n+1)) нийлбэрийг ол.',F(2,a)-F(2,b),'2/[n(n+1)]=2/n−2/(n+1); завсрын бүх гишүүд хасагдана.')
    red=k+2;blue=k
    p.mc('Ordered drawing without replacement',f'Хайрцагт {red} шар, {blue} ногоон бөмбөг бий. Буцаахгүйгээр дараалан хоёрыг авахад эхнийх шар, дараагийнх ногоон байх магадлалыг ол.',F(red*blue,(red+blue)*(red+blue-1)),'Эхний шарын магадлалыг дараагийн ногооны нөхцөлт магадлалаар үржүүл.')
    t=k
    p.mc('Radicals in arithmetic progression',f'√(2x+{6*t}), √(6x+{15*t}), √(10x+{26*t}) нь арифметик прогрессийн дараалсан гишүүд. Ялгавар эерэг бол ялгаврыг ол.',f'√{t}','Хоёр дахин квадратлаж шалгахад x=−t (бусад язгуур анхны тэгшитгэлд нийцэхгүй); гишүүд 2√t,3√t,4√t.',[f'2√{t}',f'3√{t}',f'√{2*t}',0])
    p.mc('Trapezoid diagonals',f'PQ,RS суурьтай трапецийн диагоналиуд O дээр огтолно. QO={k}, OS={2*k}, PQ={10*k}. Дундаж шугамыг ол.',15*k,'Төсөөтэй гурвалжнаас RS/PQ=OS/QO=2; дундаж (PQ+RS)/2.')
    p.mc('Log radical and arcsine domain',f'y=log₁₀√((x−{k+3})/(x−{k-2}))+arcsin(x−{k-2}) функцийн мужийг ол.',f'[{k-3}; {k-2})','arcsin-ээс k−3≤x≤k−1. Логарифмын доторх харьцаа эерэг тул x<k−2 эсвэл x>k+3. Огтлолцол ав.',[f'({k-3}; {k-2})',f'[{k-2}; {k-1}]',f'[{k-3}; {k-1}]','∅'])
    angle=12+v
    p.mc('Trig sum identity',f'((sin{2*angle}°+sin{angle}°)/(1+cos{angle}°+cos{2*angle}°))·cot{angle}°-г хялбарчил.',1,'sin2θ+sinθ=sinθ(2cosθ+1); 1+cosθ+cos2θ=cosθ(2cosθ+1).')
    p.mc('Triangle median length',f'A(0,1),B(1,{k+1}),C({2*k+2},1) гурвалжны B оройн медианы уртыг ол.',f'{k}√2','AC-ийн дундаж (k+1,1); B-ээс зөрөө (k,−k).',[f'{k}√3',f'{2*k}',f'√{2*k}',f'{k}'])
    p.mc('Derivative definition limit',f'f(x)=2x²+{k}x+1. lim[x→1](f(x)−f(1))/(x−1)-г ол.',k+4,'Уламжлалын тодорхойлолт f′(1)=4+k.')
    coefficient=f'792·{k}^5·6^7'
    # With k=6 the swapped powers 6^7·6^5 equal the key, so that form uses the wrong coefficient C(12,4) instead.
    p.mc('Binomial coefficient',f'({k}x+6)¹² задаргааны x⁵-ийн коэффициентийг ол.',coefficient,'C(12,5)=792; x⁵ үүсэхэд kx-ийг 5, 6-г 7 удаа сонгоно.',[f'792·{k}^7·6^5' if k!=6 else f'495·{k}^5·6^7',f'792·{k}^5·6^5',f'12·{k}^5·6^7',f'792·{k}^12·6^7'])
    # Original trig quadratic in sin; translate angle by k*pi.
    p.mc('Trig quadratic equation',f'2cos²(x−{k}π)−5sin(x−{k}π)+1=0 тэгшитгэлийг бод. n∈Z.',f'x={k}π+π/6+2πn эсвэл x={k}π+5π/6+2πn','s=sin(x−kπ): 2s²+5s−3=0; s=1/2 эсвэл −3. Зөвхөн 1/2 зөвшөөрөгдөнө.',[f'x={k}π−π/6+2πn',f'x={k}π+π/2+2πn',f'x={k}π+π/6+πn','Шийдгүй'])
    p.mc('Polynomial and trig integral',f'∫(x²+sin({k}x))dx-г ол.',f'x³/3−cos({k}x)/{k}+C','Зэрэгт функц ба sin-ийн интегралыг тус тус ол.',[f'x³/3+cos({k}x)/{k}+C',f'x³−cos({k}x)/{k}+C',f'2x+{k}cos({k}x)+C',f'x³/3−{k}cos({k}x)+C'])
    p.multi('2.1','Trapezoid metric geometry',f'Трапецийн сууриуд {30*k}, {5*k}, хажуу талууд {20*k}, {15*k}.', [('Дундаж шугам',F(35*k,2)),('Өндөр',12*k),('Талбай',210*k*k)],'Суурийн зөрүү 25k. Хөлийн проекц t: t²+h²=(15k)², (25k−t)²+h²=(20k)². t=9k,h=12k. S=дундаж·өндөр.')
    m=v;n=m*m+2;a=m*m+1
    coef='' if m==1 else str(m)
    # Simplifying X is the task, so its value alone (the original fraction) must not pass: exact form.
    p.multi('2.2','Conjugate radicals and cubes',f'X=(√{n}−{m})/(√{n}+{m}), Y={a}+{coef}√{n}.', [('X-ийн хураасан хэлбэр',simplest(a-m*S.sqrt(n)),{'exactForm':True,'accept':[f'{a}−{coef}√{n}',f'−{coef}√{n}+{a}']}),('X+Y',2*a),('XY',1),('X³+Y³',8*a**3-6*a)],'Хуваарийг рационалчил; X,Y хосмог, үржвэр 1. X³+Y³=(X+Y)³−3XY(X+Y).')
    h=k
    p.multi('2.3','Rational curve calculus and line geometry',f'f(x)=(x−{h})/(x−{h+1}). x>{h+1} салбарыг авч үз.', [(f'x={h+2} дээрх шүргэгч',f'y=−x+{h+4}'),(f'x={h+2},x={h+4},y=0-той хүрээлсэн талбай','2+ln3'),(f'y=2x+5-д перпендикуляр, ({h+1},1)-ийг дайрсан шулуун',f'x+2y−{h+3}=0'),(f'f(x) ба (x−{h})+5y−12=0 шулууны огтлолцлын хоорондох зай','4√26/5')],'u=x−h. f=1+1/(u−1); f′(2)=−1. Интеграл [u+ln(u−1)]₂⁴=2+ln3. Огтлолцлын u=2,6; y=2,6/5 тул зай √(16+16/25).')
    d=v+2;e=v+3;nums=list(range(10,100))
    has=lambda n,d:str(d) in str(n)
    p.multi('2.4','Counting two digit integers',f'Хоёр оронтой натурал тоонуудаас нэгийг жигд сонгоно.', [(f'{d} цифр агуулсан байх магадлал',F(sum(has(n,d) for n in nums),90)),(f'{d} эсвэл {e} цифрийн ядаж нэгийг агуулсан байх магадлал',F(sum(has(n,d) or has(n,e) for n in nums),90)),('3-д хуваагдах магадлал',F(1,3)),(f'{d} цифр агуулсан ба 3-д хуваагдах магадлал',F(sum(has(n,d) and n%3==0 for n in nums),90))],'Нийт 90 тоо. Нэг цифр агуулсан нь 18; хоёр цифрийн нэгдэл 18+18−2=34. Давхар нөхцөлд цифрийн нийлбэрийг 3-аар шалган тоол.')
    p.save()

if __name__=='__main__':
    for v in range(1,6):make(v)
